text:
{{ appsmith.store.selected_pr.REQUISITION_NUMBER || appsmith.store.selected_pr.requisition }} | {{
(() => {
	// 1. Grab the text from HEADER_NOTE (or fallback)
	let rawText = appsmith.store.selected_pr.HEADER_NOTE || "No Description";
	// 2. Strip line breaks to keep the title clean on one line
	const text = (rawText + "").replace(/[\r\n]+/g, ' ');
	// 3. Set your maximum character limit
	const limit = 150; 
	// 4. If it's too long, cut it and add "...", otherwise show full text
	return text.length > limit 
		? text.substring(0, limit).trim() + "..." 
	: text;
})()
}}
